/** Compile readable per-article HTML into the shared offline documentation snapshot. */
import fs from 'node:fs/promises';
import path from 'node:path';
import vm from 'node:vm';
import { randomUUID } from 'node:crypto';
import { pathToFileURL } from 'node:url';

const CATALOG = 'assets/js/data/docs-content.js';
const OUTPUT = 'assets/js/generated/docs-bodies.js';

/** Refuse symlinks in authoring inputs and output paths before reading or writing them. */
async function verifyLocalPath(root, relative, allowMissing = false) {
  let current = root;
  for (const part of relative.split('/')) {
    current = path.join(current, part);
    let stat;
    try { stat = await fs.lstat(current); }
    catch (error) {
      if (allowMissing && error.code === 'ENOENT') return;
      throw error;
    }
    if (stat.isSymbolicLink()) throw new Error('Refusing symbolic link in documentation path: ' + relative);
  }
}

/** Validate all source bodies before producing or checking a deterministic browser bundle. */
export async function buildDocsBundle(root, options = {}) {
  root = path.resolve(root);
  await verifyLocalPath(root, CATALOG);
  const context = vm.createContext({ window: {} });
  vm.runInContext(await fs.readFile(path.join(root, CATALOG), 'utf8'), context, { filename: CATALOG, timeout: 1000 });
  const docs = context.window.COREX_DOCS;
  if (!docs || !Array.isArray(docs.articles) || !docs.articles.length) {
    throw new Error('Documentation catalog must contain article metadata.');
  }

  const bodies = Object.create(null), ids = new Set();
  for (const article of docs.articles) {
    if (!article || typeof article.id !== 'string' || !/^[a-z0-9]+(?:[\/-][a-z0-9]+)*$/.test(article.id)) {
      throw new Error('Invalid documentation article id.');
    }
    if (ids.has(article.id)) throw new Error('Duplicate documentation article id: ' + article.id);
    ids.add(article.id);
    const expected = 'assets/content/docs/' + article.id + '.html';
    if (article.bodyFile !== expected) throw new Error('Invalid bodyFile path for ' + article.id + '; expected ' + expected);
    await verifyLocalPath(root, expected);
    const body = await fs.readFile(path.join(root, expected), 'utf8');
    bodies[article.id] = body;
  }

  // Escape script delimiters while retaining exact HTML once the browser reads the strings.
  const serialized = JSON.stringify(bodies, null, 2).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  const bundle = '/* Generated by tools/build-docs-bundle.mjs. Edit assets/content/docs/ instead. */\n' +
    '(function () {\n  \'use strict\';\n  var bodies = ' + serialized + ';\n' +
    '  var docs = window.COREX_DOCS;\n' +
    '  if (!docs || !Array.isArray(docs.articles)) throw new Error(\'Load docs-content.js before docs-bodies.js.\');\n' +
    '  // Restore the bodyHtml contract consumed by the wiki, search and full reference.\n' +
    '  docs.articles.forEach(function (article) {\n' +
    '    if (!Object.prototype.hasOwnProperty.call(bodies, article.id)) throw new Error(\'Documentation bundle missing article: \' + article.id);\n' +
    '    article.bodyHtml = bodies[article.id];\n' +
    '  });\n}());\n';

  await verifyLocalPath(root, OUTPUT, true);
  const output = path.join(root, OUTPUT);
  let current = null;
  try { current = await fs.readFile(output, 'utf8'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  if (current === bundle) return { changed: false, count: ids.size };
  if (options.check) throw new Error('Documentation bundle is stale or missing. Rebuild with: node tools/build-docs-bundle.mjs .');

  await fs.mkdir(path.dirname(output), { recursive: true });
  const temporary = output + '.' + randomUUID() + '.tmp';
  try {
    await fs.writeFile(temporary, bundle, { flag: 'wx' });
    await fs.rename(temporary, output);
  } finally { await fs.rm(temporary, { force: true }); }
  return { changed: true, count: ids.size };
}

if (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {
  try {
    const args = process.argv.slice(2), check = args.includes('--check');
    // Keep the root argument separate from the optional read-only validation switch.
    const positional = args.filter(arg => arg !== '--check');
    // Unknown CLI switches must fail rather than become filesystem roots.
    if (positional.length > 1 || positional.some(arg => arg.startsWith('--'))) {
      throw new Error('Usage: node tools/build-docs-bundle.mjs [root] [--check]');
    }
    const result = await buildDocsBundle(positional[0] || '.', { check });
    console.log((check ? 'Checked' : result.changed ? 'Updated' : 'Unchanged') + ' offline documentation bundle: ' + result.count + ' articles.');
  } catch (error) { console.error(error.message); process.exitCode = 1; }
}
